(function () { "use strict"; function paint() { if (!window.labelArt) return; document.querySelectorAll("[data-labelart]").forEach(function (el) { if (!el.getAttribute("data-done")) { el.innerHTML = window.labelArt(el.getAttribute("data-labelart")); el.setAttribute("data-done", "1"); } }); } paint(); var btn = document.querySelector("[data-lang-toggle]"); if (btn) btn.addEventListener("click", function () { setTimeout(paint, 0); }); })();